import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"Copy Trading","description":"","frontmatter":{},"headers":[],"relativePath":"guide/follow.md","filePath":"guide/follow.md","lastUpdated":1790683574000}'),o={name:"guide/follow.md"};function r(i,e,d,l,p,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="copy-trading" tabindex="-1">Copy Trading <a class="header-anchor" href="#copy-trading" aria-label="Permalink to &quot;Copy Trading&quot;">​</a></h1><p>Copy trading is the platform&#39;s social trading product: a <strong>lead trader</strong> creates a trading plan and generates a copy code, <strong>users</strong> follow with one tap using the code, and the system opens and settles positions for everyone at the set time.</p><h2 id="overall-flow" tabindex="-1">Overall flow <a class="header-anchor" href="#overall-flow" aria-label="Permalink to &quot;Overall flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Admin grants &quot;lead trading&quot; permission to a user</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>The lead trader creates a plan on the user side → a dedicated copy code is generated</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Users enter the code → follow with one tap (no need to watch the market)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>At the set time, the system opens positions in batch</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>After settlement, each user&#39;s profit or loss is written back automatically</span></span></code></pre></div><h2 id="what-operators-do" tabindex="-1">What operators do <a class="header-anchor" href="#what-operators-do" aria-label="Permalink to &quot;What operators do&quot;">​</a></h2><h3 id="_1-grant-lead-trading-permission" tabindex="-1">1. Grant lead-trading permission <a class="header-anchor" href="#_1-grant-lead-trading-permission" aria-label="Permalink to &quot;1. Grant lead-trading permission&quot;">​</a></h3><p>Not every user can issue copy codes. You must <strong>grant lead-trading permission</strong> to specific users in the admin console; users without it cannot create plans.</p><h3 id="_2-control-the-daily-code-quota" tabindex="-1">2. Control the daily code quota <a class="header-anchor" href="#_2-control-the-daily-code-quota" aria-label="Permalink to &quot;2. Control the daily code quota&quot;">​</a></h3><p>The admin console can limit <strong>how many copy codes a lead trader can issue per day</strong>, to prevent abuse.</p><h3 id="_3-copy-trading-management" tabindex="-1">3. Copy-trading management <a class="header-anchor" href="#_3-copy-trading-management" aria-label="Permalink to &quot;3. Copy-trading management&quot;">​</a></h3><p>The admin console provides full copy-trading records: who issued the code, who followed, and the results of opening and settlement.</p><h2 id="funds-safety" tabindex="-1">Funds safety <a class="header-anchor" href="#funds-safety" aria-label="Permalink to &quot;Funds safety&quot;">​</a></h2><ul><li>The whole process is managed by the system, with every movement of funds recorded</li><li><strong>A failed follow is refunded immediately to its source</strong> — there is never a case where funds are deducted but no position is opened</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>A user says the copy code is invalid?</strong> Check: ① whether the code has expired; ② whether the plan has already reached its opening time (plans that have opened no longer accept new followers); ③ whether the code was mistyped.</p><p><strong>A user followed but no position was opened?</strong> Check that entry&#39;s status in the copy-trading records. A failed follow is refunded to its source, and the user can see the refund in their ledger.</p>`,16)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
